Here's a simple implementation:

```typescript
class Stack<T> {
    private items: T[] = [];

    constructor() {}

    // Push an item onto the stack
    push(item: T): void {
        this.items.push(item);
    }

    // Pop an item from the stack
    pop(): T | undefined {
        if (this.isEmpty()) {
            return undefined;
        }
        return this.items.pop();
    }

    // Peek at the top item of the stack without removing it
    peek(): T | undefined {
        if (this.isEmpty()) {
            return undefined;
        }
        return this.items[this.items.length - 1];
    }

    // Check if the stack is empty
    isEmpty(): boolean {
        return this.items.length === 0;
    }

    // Get the size of the stack
    size(): number {
        return this.items.length;
    }

    // Clear the stack
    clear(): void {
        this.items = [];
    }
}

// Example usage
const stack = new Stack<number>();

console.log(stack.isEmpty()); // true
stack.push(10);
stack.push(20);
stack.push(30);
console.log(stack.peek()); // 30
console.log(stack.pop()); // 30
console.log(stack.size()); // 2
console.log(stack.isEmpty()); // false
stack.clear();
console.log(stack.isEmpty()); // true
```

### Explanation:
- **`push(item: T): void`**: Adds an item to the top of the stack.
- **`pop(): T | undefined`**: Removes and returns the top item of the stack. If the stack is empty, it returns `undefined`.
- **`peek(): T | undefined`**: Returns the top item of the stack without removing it. If the stack is empty, it returns `undefined`.
- **`isEmpty(): boolean`**: Returns `true` if the stack is empty, otherwise `false`.
- **`size(): number`**: Returns the number of items in the stack.
- **`clear(): void`**: Clears all items from the stack.

